const packageRoot = 'github.com/samuelpmahan/gondola/fixtures/compiled';
const wirePackage = `${packageRoot}/modulewire`;
const inputTypeID = `${wirePackage}.Input`;
const publicationTypeID = `${wirePackage}.Publication`;
const messageTypeID = 'github.com/samuelpmahan/gondola/gobi.Message';
const effectTypeID = 'github.com/samuelpmahan/gondola/gobi.Effect';
const effectsTypeID = `[]${effectTypeID}`;
const nodeTypeID = 'github.com/samuelpmahan/gondola/gobi.Node';
const schema = 'gobi.module-abi/v1';
const utf8Encoder = new TextEncoder();

// These digest pairs were generated by Go's encoding/json over the descriptor
// artifact list and body for the corresponding path code point. Keep them as
// independent vectors rather than recomputing them with this JS test helper.
export const goCanonicalDigestVectors = Object.freeze([
  Object.freeze({ name: 'less-than', codePoint: 0x3c, artifactSHA256: '9879bccd33b687e5c94f41a068b19cd244f99d92269518cabae5604f660b5947', abiSHA256: 'fadb0e4b1bfb9f8df0f3820122bae0e4ac0cf8dc7ce617a6c530ac877b10f65e' }),
  Object.freeze({ name: 'greater-than', codePoint: 0x3e, artifactSHA256: '8d7c61bbd857d7fc3f6976cf5c59c8ec0ef0deeb36489521eb835ddd288c0e48', abiSHA256: 'b51f61523780a1220b08a69a290bf4631b274d1c2e45aaa765cf2d4aef2b8723' }),
  Object.freeze({ name: 'ampersand', codePoint: 0x26, artifactSHA256: '92c235e12c682e65d3fa72769ac56e5a770da3de11ecb7051e1964841342959a', abiSHA256: '2eecb64cf3de1e7e4f9b08e17fea4153ca34b7092920168280835665182f9264' }),
  Object.freeze({ name: 'line-separator', codePoint: 0x2028, artifactSHA256: '09e0be6a2b7f32b3dd0fb7cb906f3a226af47a0593d456d357a49f79a9b7cb40', abiSHA256: 'c228cacd25641bc0d349ca769e8248d370dca24f6194be6dd85a4073071b3aad' }),
  Object.freeze({ name: 'paragraph-separator', codePoint: 0x2029, artifactSHA256: '81ebb7375be8313beea8560aea88581531caaa5dc92f64f142b27a983a8303e9', abiSHA256: '0c670923f4259e399a661f325fa80370228c5db9c1031001b319df052922b9c5' }),
]);

export async function makeValidTestPair({ childWirePackage = wirePackage } = {}) {
  return {
    parent: await makeTestModule(`${packageRoot}/moduleparent`, 'moduleparent', true),
    child: await makeTestModule(`${packageRoot}/modulechild`, 'modulechild', false, childWirePackage),
  };
}

export async function rehashTestDescriptor(descriptor) {
  descriptor.artifactSHA256 = await sha256Text(canonicalJSON(descriptor.artifacts));
  const { abiSHA256: _ignored, ...body } = descriptor;
  descriptor.abiSHA256 = await sha256Text(canonicalJSON(body));
  return descriptor;
}

async function makeTestModule(packagePath, appDir, parent, wirePackageForModule = wirePackage) {
  const stateTypeID = `${packagePath}.State`;
  const moduleInputTypeID = `${wirePackageForModule}.Input`;
  const modulePublicationTypeID = `${wirePackageForModule}.Publication`;
  const appIR = {
    schema: 'gobi.app-ir/v1',
    packagePath,
    components: [{
      id: packagePath,
      packagePath,
      stateType: stateTypeID,
      messageType: messageTypeID,
      init: `${packagePath}.Init`,
      update: `${packagePath}.Update`,
      view: `${packagePath}.View`,
      capabilities: ['view.node'],
    }],
    symbols: [],
    types: [
      { id: 'bool', kind: 'bool', jsRepresentation: 'direct' },
      { id: 'float64', kind: 'float64', jsRepresentation: 'number' },
      { id: 'int', kind: 'int', bits: 64, jsRepresentation: 'number' },
      { id: 'string', kind: 'string', jsRepresentation: 'direct' },
      { id: stateTypeID, kind: 'struct', fields: [
        { name: 'Revision', type: 'int' }, { name: 'Locked', type: 'bool' }, { name: 'Count', type: 'float64' },
        ...(parent ? [{ name: 'PublishedRevision', type: 'int' }] : []),
      ], jsRepresentation: 'class' },
      { id: messageTypeID, kind: 'struct', fields: [{ name: 'Name', type: 'string' }, { name: 'Arg', type: 'string' }], jsRepresentation: 'class' },
      { id: effectTypeID, kind: 'struct', fields: [
        { name: 'Kind', type: 'string' }, { name: 'Name', type: 'string' }, { name: 'Arg', type: 'string' }, { name: 'Reply', type: 'string' },
      ], jsRepresentation: 'class' },
      { id: effectsTypeID, kind: 'slice', elemType: effectTypeID, jsRepresentation: 'array-or-goscript-slice' },
      { id: nodeTypeID, kind: 'struct', fields: [{ name: 'Tag', type: 'string' }], jsRepresentation: 'class' },
      { id: moduleInputTypeID, kind: 'struct', fields: [
        { name: 'Step', type: 'int' }, { name: 'Locked', type: 'bool' }, { name: 'Revision', type: 'int' },
      ], jsRepresentation: 'class' },
      { id: modulePublicationTypeID, kind: 'struct', fields: [
        { name: 'Count', type: 'float64' }, { name: 'Revision', type: 'int' },
      ], jsRepresentation: 'class' },
    ],
  };
  const roles = [
    { name: 'Init', signature: { params: [], results: [stateTypeID] } },
    { name: 'Update', signature: { params: [stateTypeID, messageTypeID], results: [stateTypeID, effectsTypeID] } },
    { name: 'View', signature: { params: [stateTypeID], results: [nodeTypeID] } },
    ...(parent
      ? [
          { name: 'Output', signature: { params: [stateTypeID], results: [moduleInputTypeID] } },
          { name: 'Receive', signature: { params: [stateTypeID, modulePublicationTypeID], results: [stateTypeID] } },
        ]
      : [
          { name: 'Input', signature: { params: [stateTypeID, moduleInputTypeID], results: [stateTypeID] } },
          { name: 'Publication', signature: { params: [stateTypeID], results: [modulePublicationTypeID] } },
        ]),
  ].sort((left, right) => compareGoStrings(left.name, right.name));
  appIR.symbols = roles.map((role) => ({
    id: `${packagePath}.${role.name}`,
    packagePath,
    name: role.name,
    signature: role.signature,
    span: { file: 'app.go', startByte: 0, endByte: 0 },
    calls: [],
  }));

  const encoder = new TextEncoder();
  const artifactBytes = new Map([
    [`apps/${appDir}/app-ir.json`, encoder.encode(JSON.stringify(appIR))],
    [`apps/${appDir}/gobi-compiled.mjs`, encoder.encode('export const gobiCompiled = {}')],
    [`apps/${appDir}/encoder.mjs`, encoder.encode('export const encoder = {}')],
    [`apps/${appDir}/components.gen.mjs`, encoder.encode('export const components = {}')],
  ]);
  const artifacts = [];
  for (const path of [...artifactBytes.keys()].sort(compareGoStrings)) {
    const bytes = artifactBytes.get(path);
    artifacts.push({ path, bytes: bytes.byteLength, sha256: await sha256Bytes(bytes) });
  }
  const descriptor = {
    schema,
    appIRSchema: appIR.schema,
    componentID: packagePath,
    packagePath,
    artifactSHA256: await sha256Text(canonicalJSON(artifacts)),
    artifacts,
    roles: roles.map((role) => ({ name: role.name, symbol: `${packagePath}.${role.name}`, signature: structuredClone(role.signature) })),
    types: structuredClone(deriveTypes(appIR)),
    capabilities: ['view.node'],
    abiSHA256: '',
  };
  await rehashTestDescriptor(descriptor);
  const descriptorBytes = encoder.encode(`${JSON.stringify(descriptor, null, 2)}\n`);
  return { descriptor, descriptorBytes, appIR, artifactBytes };
}

function deriveTypes(appIR) {
  const byID = new Map(appIR.types.map((info) => [info.id, info]));
  const visited = new Set();
  const visit = (id) => {
    if (visited.has(id)) return;
    const info = byID.get(id);
    if (!info) throw new Error(`missing test type ${id}`);
    visited.add(id);
    for (const field of info.fields ?? []) visit(field.type);
    if (info.elemType) visit(info.elemType);
  };
  for (const role of appIR.symbols) {
    for (const id of [...role.signature.params, ...role.signature.results]) visit(id);
  }
  return [...visited].sort(compareGoStrings).map((id) => byID.get(id));
}

async function sha256Bytes(bytes) {
  const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes);
  return [...new Uint8Array(digest)].map((value) => value.toString(16).padStart(2, '0')).join('');
}

async function sha256Text(text) {
  return sha256Bytes(new TextEncoder().encode(text));
}

function canonicalJSON(value) {
  if (value === null || typeof value === 'boolean') return JSON.stringify(value);
  if (typeof value === 'string') return goJSONString(value);
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError('canonical JSON cannot contain non-finite numbers');
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) return `[${value.map(canonicalJSON).join(',')}]`;
  return `{${Object.keys(value).sort(compareGoStrings).map((key) => `${goJSONString(key)}:${canonicalJSON(value[key])}`).join(',')}}`;
}

function goJSONString(value) {
  return JSON.stringify(value).replace(/[<>\u0026\u2028\u2029]/g, (character) =>
    `\\u${character.codePointAt(0).toString(16).padStart(4, '0')}`);
}

function compareGoStrings(left, right) {
  const leftBytes = utf8Encoder.encode(left);
  const rightBytes = utf8Encoder.encode(right);
  const commonLength = Math.min(leftBytes.length, rightBytes.length);
  for (let index = 0; index < commonLength; index += 1) {
    if (leftBytes[index] !== rightBytes[index]) return leftBytes[index] - rightBytes[index];
  }
  return leftBytes.length - rightBytes.length;
}
